(* [comment removed for export] *)
Definition PTS (i : nat) (c : CC.cutpoint) (E1 : env) (M' : mem) : Prop :=
  exists (ps2 : PML.pstate) (code : Z) (g' : PML.ls_state),
    bv_unsigned (ev E1 (CC.cp_nx c - APC.NCS - 5)) = code /\ PML.parser_at M' P ps2 /\ PML.wf_ps ps2 /\ PML.win_ok M' LBo ps2 /\ PML.buf_bound ps2 B /\ PML.ec_at M' E code /\ (code <> 0 -> PML.ps_more ps2 = false) /\
    PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\ CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps2 /\ (PSIU.skip_cut i = true -> code = 0) /\
    (code = 0 ->
       PML.ps_more ps2 = true /\ snd (PSA.wincells (PML.ps_win ps2)) = wend /\ seg <= fst (PSA.wincells (PML.ps_win ps2)) <= wend /\
       (PSM2.under0 i = true -> In (PML.ps_st ps2) [PML.ST_ACCEPT; PML.ST_EXPECT_COMMA_OR_END]) /\
       (PSM2.in_loop i = true ->
          if Z.eqb (PSM2.reent_pc i) L2PC then PML.winlen ps2 = bv_unsigned (ev E1 53)
          else PML.winlen ps2 + 1 <= bv_unsigned (ev E1 53) \/ (PML.winlen ps2 = bv_unsigned (ev E1 53) /\ PSIU.RANK ps2 + 1 <= bv_unsigned (ev E1 54))) /\
       PSIU.xsync ps2 eg) /\
    PSIU.PTW I eg i ps2 code M'.      (* [comment removed for export] *)
Lemma pt_state : forall i c k ps1 pc E1 R1 E' R' (M1 M' : mem) model1, is_leaf i c k ps1 (CC.TOther pc) -> kind_of i = KPt ->
  (if PSM2.cur_cut i then PB.has (SR.ps_cells ps1) (KWord (SA Pb 200) 8 (EVar (PSM3.a0v_of c))) else Nat.eqb (length (CC.cp_F c)) 1) = true -> (74 <= CC.cp_nx c)%nat ->
  match CC.cp_F c with [_; (_, o1, _)] => Z.eqb o1 200 | _ => true end = true ->
